{"content": "#!/usr/bin/env python3
"""ezmaze oracle attack lab: exact toPath/stats + fingerprint (+ discarded
local-search baselines, kept only as negative controls).

STATUS (agent 72): the stochastic/local-search direction is DEAD.  Simulated
annealing / coordinate descent over 64 base-4 digits do not converge: the
objective sum_u |x_u(m')-x_u| + |y_u(m')-y_u| is a rugged spin-glass-like
function (every digit flip perturbs every query by O(1) through carry chains,
and the constraints are global histogram sums), so there is no usable gradient
at 128 unknown bits.  It is superseded by the exact LENGTH ORACLE:

  r = t*(4^K - 1), 1 <= m*t <= 4^K, m*r < n
  ==>  m*r = (m*t - 1)*4^K + (4^K - m*t)
  ==>  oracle's x - y  =  K - len_base4(m*t - 1)      [len_base4(0) := 0]

i.e. each query is a length measurement; log-bisection over t plus
pow(cand,e,n)==c recovers m exactly in ~135 queries.  Verified independently in
/workspace/verify_length_oracle.py, /workspace/verify_end_to_end.py and
/workspace/verify_exact_search.py (real RSA keys, 0 failures).

Oracle model (matches chall.py):
  secret m (< 4^64), base-4 digits with L=0,R=1,U=2,D=3; leading zeros dropped
  (toPath: x=0 -> "L").  Query(choose u) -> (count(R)-count(L), count(U)-count(D)).
"""
import random
import sys
import time

DIRS = "LRUD"


# ---------------------------------------------------------------- exact oracle
def to_path(x: int) -> str:
    s = bin(x)[2:]
    if len(s) % 2 == 1:
        s = "0" + s
    return "".join(DIRS[int(s[i:i + 2], 2)] for i in range(0, len(s), 2))


def final_position(path: str):
    return (path.count("R") - path.count("L"), path.count("U") - path.count("D"))


def stats_int(x: int):
    return final_position(to_path(x))


def digits4(x: int):
    ds = []
    while x:
        ds.append(x & 3)
        x >>= 2
    ds.reverse()
    return ds


def stats_fast(x: int):
    """digit histogram, identical semantics to toPath (x = 0 -> 'L' -> (-1,0))."""
    if x == 0:
        return (-1, 0)          # toPath(0) == "L"   (NOT "LL")
    n0 = n1 = n2 = n3 = 0
    while x:
        d = x & 3
        if d == 0:
            n0 += 1
        elif d == 1:
            n1 += 1
        elif d == 2:
            n2 += 1
        else:
            n3 += 1
        x >>= 2
    return (n1 - n0, n2 - n3)


def fingerprint(m: int, us):
    return tuple(stats_int(m * u) for u in us)


def to_int(p: str) -> int:
    r = 0
    for d in p:
        r = r * 4 + DIRS.index(d)
    return r


def len4(x: int) -> int:
    return 0 if x == 0 else (x.bit_length() + 1) // 2


def rand_secret(n_digits=64, rng=random):
    p = "".join(rng.choice(DIRS) for _ in range(n_digits))
    return p, to_int(p)


# ------------------------------------------------------- multiplier selection
def mults_small(t):
    out, u = [], 1
    while len(out) < t:
        if u % 4:
            out.append(u)
        u += 1
    return out


def mults_random(t, bits=16, rng=random):
    out = []
    while len(out) < t:
        u = rng.getrandbits(bits) | 1
        if u % 4:
            out.append(u)
    return out


# ------------------------------------------- exact length-oracle recovery (WIN)
def length_oracle(m, t, K, n):
    """simulated service answer: len_base4(m*t - 1) from the reported x-y."""
    r = t * (4 ** K - 1)
    v = m * r
    assert v < n, "wrap: m*r >= n"
    x, y = stats_int(v)
    return K - (x - y)


def recover_length_oracle(m, n, K=130, ndigits=64):
    """exact recovery in ~135 queries: t=1 -> len4(m-1), then exact-boundary
    binary search for t* = min{t : m*t > 4^(K-1)} giving a width<1 bracket."""
    cache = {}

    def meas(t):
        if t not in cache:
            cache[t] = length_oracle(m, t, K, n)
        return cache[t]

    l1 = meas(1)
    ahi = 4 ** l1
    if ahi == 1:
        return 1, len(cache)
    t_max = (4 ** K) // ahi
    assert meas(t_max) >= K
    lo, hi = 1, t_max
    while lo < hi:
        mid = (lo + hi) // 2
        if meas(mid) >= K:
            hi = mid
        else:
            lo = mid + 1
    tstar = lo
    a = 4 ** (K - 1) // tstar + 1
    b = 4 ** (K - 1) // (tstar - 1)
    assert a == b and a == m, (a, b, m)
    return a, len(cache)


# --------------------------------------------------------- baseline searches
def objective(m, us, targets):
    s = 0
    for u, (tx, ty) in zip(us, targets):
        x, y = stats_fast(m * u)
        s += abs(x - tx) + abs(y - ty)
    return s


def recover_coord(targets, us, ndigits=64, restarts=4, sweeps=6, rng=random):
    """random-restart coordinate descent (negative control: does not work)."""
    best = None
    for _ in range(restarts):
        m = sum(rng.randrange(4) << (2 * i) for i in range(ndigits))
        cur = objective(m, us, targets)
        for _ in range(sweeps):
            improved = False
            for i in range(ndigits):
                base = m - ((m >> (2 * i)) & 3) * 4 ** i
                for d in range(4):
                    m2 = base + d * 4 ** i
                    c2 = objective(m2, us, targets)
                    if c2 < cur:
                        cur, m, improved = c2, m2, True
            if not improved:
                break
        if cur == 0:
            return m
        if best is None or cur < best[0]:
            best = (cur, m)
    return None


def recover_sa(targets, us, ndigits=64, iters=200000, t0=8.0, t1=0.05,
               restarts=2, rng=random):
    """simulated annealing over base-4 digits (negative control: fails)."""
    import math
    for _ in range(restarts):
        m = sum(rng.randrange(4) << (2 * i) for i in range(ndigits))
        cur = objective(m, us, targets)
        for it in range(iters):
            temp = t0 * (t1 / t0) ** (it / iters)
            i = rng.randrange(ndigits)
            old = (m >> (2 * i)) & 3
            m2 = m - old * 4 ** i + rng.randrange(4) * 4 ** i
            c2 = objective(m2, us, targets)
            if c2 <= cur or rng.random() < math.exp(-(c2 - cur) / max(temp, 1e-9)):
                m, cur = m2, c2
                if cur == 0:
                    return m
    return None


def make_instance(ndigits=64, T=1000, kind="small", rng=random):
    _, m = rand_secret(ndigits, rng)
    us = mults_small(T) if kind == "small" else mults_random(T, 32, rng)
    return m, us, [stats_fast(m * u) for u in us]


def main(argv):
    what = argv[1] if len(argv) > 1 else "selftest"
    if what == "selftest":
        rng = random.Random(1)
        for x in [0, 1, 2, 3, 4, 5, 15, 16, 255, 4 ** 64 - 1, 12345678901234567890]:
            assert stats_int(x) == stats_fast(x), (x, stats_int(x), stats_fast(x))
        _, m = rand_secret(64, rng)
        n = (1 << 1023) | 1
        rec, q = recover_length_oracle(m, n)
        print(f"selftest ok; length-oracle recovered {rec == m} in {q} queries")
        return
    if what == "bench":
        rng = random.Random(5)
        print("# local-search negative controls (expected to fail at 64 digits)")
        for ndig, T in [(8, 12), (12, 20), (16, 24), (24, 32), (64, 40)]:
            m, us, tg = make_instance(ndig, T, "small", rng)
            t0 = time.time()
            r = recover_coord(tg, us, ndig, restarts=3, rng=rng)
            print(f"coord ndigits={ndig:2d} T={T}: success={r == m} "
                  f"({time.time()-t0:.1f}s)")
            t0 = time.time()
            r = recover_sa(tg, us, ndig, iters=40000, rng=rng)
            print(f"SA    ndigits={ndig:2d} T={T}: success={r == m} "
                  f"({time.time()-t0:.1f}s)")
        return
    if what == "length":
        rng = random.Random(11)
        ok = 0
        N = 50
        qs = []
        for _ in range(N):
            _, m = rand_secret(64, rng)
            n = (rng.getrandbits(1024) | (1 << 1023)) * 2 + 1
            rec, q = recover_length_oracle(m, n)
            ok += (rec == m)
            qs.append(q)
        print(f"length-oracle: {ok}/{N} recovered, queries "
              f"{min(qs)}/{sum(qs)/len(qs):.1f}/{max(qs)}")
        return
    print("modes: selftest | bench | length")


if __name__ == "__main__":
    main(sys.argv)
